'use client';
import React,{useEffect,useState,useRef} from 'react';
import {ArrowRight,ArrowUpRight,BookOpen,BriefcaseBusiness,Building2,Check,CheckCheck,ChevronRight,ClipboardList,Clock,FileText,Flame,GraduationCap,Heart,Home,Image as ImageIcon,LayoutDashboard,Leaf,LogOut,Mail,Menu,MoreHorizontal,Play,Plus,Search,Settings,ShieldCheck,Sparkles,Target,TrendingUp,Users,X,Download,Upload,Eye,Pencil,History,AlertCircle,Bell,CalendarDays,CheckCircle2,LockKeyhole,Send,Archive} from 'lucide-react';
import {pages as initialPages,roleNames,defaultSettings} from '../lib/content';
const img='/images/';
const statuses=['Шинэ','Холбоо барьсан','Үнэлгээ хийж байгаа','Үйлчилгээ эхэлсэн','Хаагдсан','Татгалзсан','Цуцлагдсан'];
const freq:any={once:'Нэг удаа',daily:'Өдөр бүр',weekly:'7 хоног бүр'};
const fmt=(s:string)=>s?new Date(s).toLocaleString('mn-MN',{timeZone:'Asia/Ulaanbaatar',dateStyle:'short',timeStyle:'short'}):'—';
const qblank=()=>Array.from({length:5},()=>({text:'',options:['','','',''],correct:0}));
const due=(t:any,date:string)=>t.active&&date>=t.date&&(t.recurrence==='daily'||t.recurrence==='weekly'&&new Date(t.date).getDay()===new Date(date).getDay()||t.date===date);
async function api(action:string,b:any={}){const r=await fetch('/api/jura',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...b})});const d:any=await r.json();if(!r.ok)throw new Error(d.error||'Үйлдэл амжилтгүй.');return d}
function Field({label,children,...props}:any){return <label className="field"><span>{label}</span>{children||<input {...props}/>}</label>}
function Button({children,className='',...props}:any){return <button className={'btn '+className} {...props}>{children}</button>}
function Empty({title='Одоогоор мэдээлэл алга',text='Шинэ мэдээлэл нэмэхэд энэ хэсэгт харагдана.',action}:any){return <div className="empty"><div className="empty-icon"><Leaf size={24}/></div><h3>{title}</h3><p>{text}</p>{action}</div>}
function Badge({children,tone=''}:any){return <span className={'badge '+tone}>{children}</span>}
function Stat({label,value,sub,icon:Icon=TrendingUp,pct}:any){return <div className="stat"><span className="stat-icon"><Icon size={23}/></span><div><span className="stat-label">{label}</span><strong>{value}</strong><small>{sub}</small></div>{pct!==undefined&&<div className="ring small" style={{'--p':pct} as any}><b>{pct}%</b></div>}</div>}
function Progress({value=0}:any){return <div className="progress"><i style={{width:value+'%'}}/></div>}
function Logo({light=false}:any){return <img className="brand-logo" src={img+(light?'logo-dark.png':'logo-gold.png')} alt="JURA CONSULTING"/>}
function Trend({completions=[]}:any){const days=Array.from({length:7},(_,i)=>{const d=new Date(Date.now()-(6-i)*86400000);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ulaanbaatar',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)});const values=days.map(d=>completions.filter((c:any)=>c.date===d).length);const max=Math.max(1,...values);return <div className="trend"><div className="chart-grid"><span>{max}</span><span>{Math.round(max/2)}</span><span>0</span><svg viewBox="0 0 600 150" preserveAspectRatio="none" role="img" aria-label="Сүүлийн 7 хоногийн гүйцэтгэл"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#d4af7c" stopOpacity=".3"/><stop offset="1" stopColor="#d4af7c" stopOpacity="0"/></linearGradient></defs>{[20,75,130].map(y=><line key={y} x1="0" y1={y} x2="600" y2={y} stroke="#ebe7de" strokeDasharray="4 5"/>)}<path d={`M 0 140 ${values.map((v,i)=>`L ${i*100} ${130-v/max*110}`).join(' ')} L 600 140 Z`} fill="url(#area)"/><polyline points={values.map((v,i)=>`${i*100},${130-v/max*110}`).join(' ')} stroke="#bd945b" strokeWidth="3" fill="none"/>{values.map((v,i)=><circle key={i} cx={i*100} cy={130-v/max*110} r="4" fill="#b99460"/>)}</svg></div><div className="chart-labels">{days.map(d=><span key={d}>{d.slice(5).replace('-','/')}</span>)}</div></div>}
export default function Jura(){
 const [path,setPath]=useState('/'),[pages,setPages]=useState<any>(initialPages),[contact,setContact]=useState<any>({phone:defaultSettings.contactPhone,email:defaultSettings.contactEmail,address:defaultSettings.contactAddress}),[data,setData]=useState<any>(null),[user,setUser]=useState<any>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[modal,setModal]=useState<any>(null),[mobile,setMobile]=useState(false),[search,setSearch]=useState(''),[filter,setFilter]=useState('all'),[lesson,setLesson]=useState<any>(null),[answers,setAnswers]=useState<any>({}),[result,setResult]=useState<any>(null),[selectedChild,setSelectedChild]=useState(''),[cmsPage,setCmsPage]=useState('home'),[cmsForm,setCmsForm]=useState<any>(initialPages.home),[preview,setPreview]=useState(false);
 const videoRef=useRef<HTMLVideoElement>(null);const lastTick=useRef(0);
 const go=(p:string)=>{window.history.pushState({},'',p);setPath(p);setSearch('');setFilter('all');setMobile(false);setError('');setResult(null);window.scrollTo(0,0)};
 const refreshPublic=async()=>{const r=await fetch('/api/jura');if(!r.ok)throw new Error('Сервертэй холбогдож чадсангүй.');const d:any=await r.json();setPages(d.pages);setContact(d.contact);setUser(d.user);return d.user};
 const refresh=async()=>{const r=await fetch('/api/jura?view=app');const d:any=await r.json();if(!r.ok){if(r.status===401){setUser(null);setData(null)}throw new Error(d.error)}setData(d);setUser(d.user);return d};
 useEffect(()=>{setPath(window.location.pathname);const on=()=>setPath(window.location.pathname);window.addEventListener('popstate',on);refreshPublic().then(u=>u&&refresh()).catch(e=>setError(e.message)).finally(()=>setLoading(false));return()=>window.removeEventListener('popstate',on)},[]);
 useEffect(()=>{const close=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!busy)setModal(null)};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[busy]);
 useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(id)},[toast]);
 const perform=async(action:string,b:any={},message='Амжилттай хадгаллаа.')=>{setBusy(true);setError('');try{const d=await api(action,b);await refresh();if(action==='cms'||action==='rollback'||action==='settings')await refreshPublic();if(message)setToast(message);return d}catch(e:any){setError(e.message);throw e}finally{setBusy(false)}};
 const upload=async(f:File,kind='image')=>{setBusy(true);try{const form=new FormData();form.set('file',f);const r=await fetch('/api/upload?kind='+kind,{method:'POST',body:form});const d:any=await r.json();if(!r.ok)throw new Error(d.error);setToast('Файл хадгаллаа.');return d.url}catch(e:any){setError(e.message);throw e}finally{setBusy(false)}};
 useEffect(()=>{if(!path.startsWith('/academy/')||!user)return;const id=path.split('/').pop();setLesson(null);setAnswers({});fetch('/api/jura?view=lesson&id='+encodeURIComponent(id||'')).then(async r=>{const d:any=await r.json();if(!r.ok)throw new Error(d.error);setLesson(d)}).catch(e=>setError(e.message))},[path,user?.id]);
 useEffect(()=>{const row=data?.cms?.find((c:any)=>c.id===cmsPage);setCmsForm(row?JSON.parse(row.draft):pages[cmsPage])},[cmsPage,data?.cms,pages]);
 const onSubmit=(fn:any)=>(e:any)=>{e.preventDefault();fn(e).catch(()=>{})};
 const homeFor=(u:any)=>u.role==='admin'?'/admin':u.role==='manager'?'/company':u.role==='parent'?'/parent':'/dashboard';
 const activeKey=path.split('/')[1]||'home';const publicPage=['/','/personal','/work','/kids'].includes(path);const isLogin=path==='/login';
 const list=data?.users||[],tasks=data?.tasks||[],completions=data?.completions||[],lessons=data?.lessons||[];const date=data?.date||new Date().toISOString().slice(0,10);
 const myTasks=tasks.filter((t:any)=>t.user_id===user?.id&&due(t,date));const myDone=myTasks.filter((t:any)=>completions.some((c:any)=>c.task_id===t.id&&c.date===date));
 const targetChild=list.find((x:any)=>x.id===selectedChild)||list.find((x:any)=>x.role==='kids');
 const calc=(id?:string)=>{const ts=tasks.filter((t:any)=>!id||t.user_id===id).filter((t:any)=>due(t,date));const cs=ts.filter((t:any)=>completions.some((c:any)=>c.task_id===t.id&&c.date===date));return {total:ts.length,done:cs.length,percent:ts.length?Math.round(cs.length/ts.length*100):0}};
 const streak=(id:string)=>{const days=new Set(completions.filter((c:any)=>c.user_id===id).map((c:any)=>c.date));let count=0;const base=new Date(date+'T00:00:00Z');if(!days.has(date))base.setUTCDate(base.getUTCDate()-1);for(let i=0;i<4000;i++){const d=base.toISOString().slice(0,10);if(!days.has(d))break;count++;base.setUTCDate(base.getUTCDate()-1)}return count};
 const openTask=(t?:any)=>setModal({type:'task',form:t?{...t,evidence_required:!!t.evidence_required,active:!!t.active}:{title:'',description:'',user_id:user?.id,date,time:'09:00',recurrence:'once',priority:'normal',evidence_required:false,active:true}});
 const openUser=(u?:any)=>setModal({type:'user',form:u?{...u,password:'',consent:!!u.consent_at}:{name:'',username:'',email:'',phone:'',role:'personal',organization_id:'',parent_id:'',password:'',status:'active',consent:false}});
 const openLesson=(l?:any)=>setModal({type:'lesson',form:l?{...l,questions:l.questions||qblank()}:{title:'',description:'',category:'all',module:'JURA Academy',position:0,thumbnail:img+'jura-academy-learner.webp',video:'',duration:0,questions:qblank(),status:'draft'}});
 const updateModal=(k:string,v:any)=>setModal((m:any)=>({...m,form:{...m.form,[k]:v}}));
 const download=async(table:string)=>{try{const r=await fetch('/api/jura?view=export&table='+table);const d:any=await r.json();if(!r.ok)throw new Error(d.error);const rows=d.rows;if(!rows.length){setToast('Экспортлох мэдээлэл алга.');return}const cols=Object.keys(rows[0]);const cell=(x:any)=>{let v=String(x??'');if(/^[=+\-@]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'};const csv='\uFEFF'+[cols.map(cell).join(','),...rows.map((row:any)=>cols.map(k=>cell(row[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='JURA-'+table+'-'+date+'.csv';a.click();URL.revokeObjectURL(url)}catch(e:any){setError(e.message)}};
 const NavLink=({to,children}:any)=><a href={to} onClick={e=>{e.preventDefault();go(to)}} className={path===to?'selected':''}>{children}</a>;
 function PublicNav(){return <header className="public-nav"><a href="/" onClick={e=>{e.preventDefault();go('/')}}><Logo/></a><nav className={mobile?'show':''}><NavLink to="/">Үндсэн нүүр</NavLink><NavLink to="/personal">Хувь хүн</NavLink><NavLink to="/work">Байгууллага</NavLink><NavLink to="/kids">Хүүхэд</NavLink><a href="#contact">Холбоо барих</a></nav><div className="nav-actions"><Button className="ghost-light" onClick={()=>go(user?homeFor(user):'/login')}>{user?'Миний кабинет':'Нэвтрэх'}</Button><Button onClick={()=>{if(activeKey==='home')go('/personal');else document.getElementById('application')?.scrollIntoView({behavior:'smooth'})}}>Хүсэлт илгээх <ArrowRight size={15}/></Button><button className="mobile-menu" aria-label="Цэс" onClick={()=>setMobile(!mobile)}><Menu/></button></div></header>}
 function Footer(){return <footer id="contact"><div className="footer-main"><div><Logo/><p>Жижиг өөрчлөлт.<br/>Том боломж.</p></div><div><h4>Үйлчилгээ</h4><NavLink to="/personal">JURA PERSONAL</NavLink><NavLink to="/work">JURA WORK</NavLink><NavLink to="/kids">JURA KIDS</NavLink></div><div><h4>Холбоо барих</h4><a href={'tel:'+contact.phone.replace(/\s/g,'')}><span aria-hidden="true">📞</span> {contact.phone}</a><a href={'mailto:'+contact.email}><span aria-hidden="true">✉</span> {contact.email}</a><p>Хаяг: {contact.address}</p></div><div><h4>Таны дараагийн алхам</h4><p>Танд тохирох шийдлийг хамт олъё.</p><Button onClick={()=>go('/personal')}>Зөвлөгөө авах <ArrowRight size={15}/></Button></div></div><div className="footer-bottom"><span>© {new Date().getFullYear()} JURA Consulting. Бүх эрх хуулиар хамгаалагдсан.</span><button onClick={()=>setModal({type:'privacy'})}>Нууцлалын мэдээлэл</button><span>SMALL CHANGES. BIG FUTURES.</span></div></footer>}
 function AppForm({type}:any){return <form className="application-form" onSubmit={onSubmit(async(e:any)=>{setBusy(true);setError('');const f=e.currentTarget;const d:any=Object.fromEntries(new FormData(f));d.consent=d.consent==='on';try{const r=await api('application',{type,data:d,website:d.website});f.reset();setModal({type:'submitted',id:r.id})}catch(x:any){setError(x.message)}finally{setBusy(false)}})}><div className="form-heading"><ShieldCheck size={26}/><div><h3>{type==='kids'?'Хөтөлбөрт бүртгүүлэх':'Үйлчилгээ авах хүсэлт'}</h3><p>Мэдээллээ үлдээгээрэй. Бид тантай холбогдоно.</p></div></div><div className="fields"><Field label={type==='kids'?'Эцэг эхийн нэр *':'Таны нэр *'} name="name" required maxLength={120}/><Field label="Утасны дугаар *" name="phone" type="tel" required pattern="[+0-9 -]{8,20}"/><Field label="Имэйл хаяг *" name="email" type="email" required/>{type==='work'&&<><Field label="Байгууллагын нэр *" name="company" required/><Field label="Албан тушаал" name="position"/><Field label="Ажилтны тоо *" name="employees" type="number" min="1" required/></>}{type==='kids'&&<><Field label="Хүүхдийн нэр *" name="childName" required/><Field label="Нас (12–16) *" name="age" type="number" min="12" max="16" required/><Field label="Сургууль *" name="school" required/><Field label="Анги *" name="grade" required/><Field label="Хобби, сонирхол" name="hobby"/><Field label="Хүүхэдтэй хамаарах төрөл *"><select name="relationship" required><option value="">Сонгох</option><option>Ээж</option><option>Аав</option><option>Асран хамгаалагч</option></select></Field></>}</div><Field label="Зорилго, хэрэгцээ"><textarea name="goal" placeholder="Та юуг өөрчлөхийг хүсэж байна вэ?" maxLength={2000}/></Field>{type==='personal'&&<Field label="Одоогийн эмх цэгцийн асуудал"><textarea name="problem" maxLength={2000}/></Field>}<Field label="Нэмэлт тайлбар"><textarea name="comment" rows={2} maxLength={2000}/></Field><input name="website" className="honeypot" tabIndex={-1} autoComplete="off" aria-hidden="true"/><label className="check-label"><input type="checkbox" name="consent" required/><span>{type==='kids'?'Хүүхдийн мэдээллийг хүсэлт шийдвэрлэх зорилгоор боловсруулахыг асран хамгаалагчийн хувиар зөвшөөрч байна.':'Хүсэлтийг шийдвэрлэх зорилгоор мэдээлэл боловсруулахыг зөвшөөрч байна.'} <button type="button" className="text-link" onClick={()=>setModal({type:'privacy'})}>Нууцлал</button></span></label><Button disabled={busy} className="full">{busy?'Илгээж байна…':'Хүсэлт илгээх'} <ArrowRight size={16}/></Button><p className="secure-note"><LockKeyhole size={12}/> Мэдээлэл зөвхөн эрх бүхий админд харагдана.</p></form>}
 function Public(){const key=activeKey;const p=pages[key]||pages.home;const service=key!=='home';const benefits:any={personal:[[Home,'Өөрийн орон зай','Танд тохирсон хадгалалт'],[Clock,'Тогтвортой хэмнэл','Өдөр тутмын энгийн дадал'],[Heart,'Тав тухтай амьдрал','Хэрэгцээнд нийцсэн орчин'],[Leaf,'Урт хугацааны өөрчлөлт','Дадлаа хадгалах систем']],work:[[BriefcaseBusiness,'5S & Kaizen','Эмх цэгцийн нэгдсэн стандарт'],[Users,'Багийн оролцоо','Хүн бүрийн жижиг алхам'],[TrendingUp,'Бодит гүйцэтгэл','Даалгавар, аудит, тайлан'],[FileText,'Дижитал эмх цэгц','Файл, и-мэйл, ажлын урсгал']],kids:[[BookOpen,'Суралцах дадал','Өөрийн орчноо удирдах'],[Target,'Бие даасан байдал','Хариуцлагатай жижиг алхам'],[Users,'Гэр бүлийн дэмжлэг','Эцэг эхтэй хамтдаа'],[Heart,'Урамтай өсөлт','Ахиц бүрээ харах']]};return <>{PublicNav()}<main className="public-main"><section className={'hero '+(key==='kids'?'kids-hero':'')} style={{backgroundImage:`linear-gradient(90deg,rgba(17,17,15,.94) 0%,rgba(17,17,15,.73) 35%,rgba(17,17,15,.1) 78%),url('${p.image}')`}}><div className="hero-copy"><span className="eyebrow">{p.eyebrow}</span><h1>{p.title}</h1><p>{p.description}</p><div className="hero-buttons"><Button onClick={()=>service?document.getElementById('application')?.scrollIntoView({behavior:'smooth'}):document.getElementById('services')?.scrollIntoView({behavior:'smooth'})}>{p.cta} <ArrowRight size={17}/></Button><button className="play-link" onClick={()=>document.getElementById('method')?.scrollIntoView({behavior:'smooth'})}><span><Play size={14}/></span> JURA аргачлал</button></div><div className="hero-foot"><span><ShieldCheck size={17}/> Хувийн нууцыг хүндэтгэнэ</span><span><Sparkles size={17}/> Танд тохирсон шийдэл</span></div></div>{key==='kids'&&<div className="hero-form" id="application">{AppForm({type:"kids"})}</div>}</section>{!service?<><section className="service-cards" id="services">{['personal','work','kids'].map(k=><article key={k} style={{backgroundImage:`linear-gradient(90deg,#181613dc,transparent),url('${pages[k].image}')`}}><span className="eyebrow">JURA {k.toUpperCase()}</span><h2>{k==='personal'?'Өөртөө цаг гарга.\nЭмх цэгцтэй амьдар.':k==='work'?'Эмх цэгцтэй баг.\nИлүү бүтээмжтэй.':'Жижиг дадлууд.\nТом боломж.'}</h2><Button onClick={()=>go('/'+k)}>Дэлгэрэнгүй <ArrowUpRight size={14}/></Button></article>)}</section><section className="why section"><div className="section-title"><span className="eyebrow">WHY JURA</span><h2>Яагаад<br/>JURA гэж?</h2><p>Нэг удаагийн цэгцлэлтээс<br/>тогтвортой дадал хүртэл.</p></div>{[[ShieldCheck,'Хувийн нууц, хүндлэл','Таны орон зай, шийдвэрийг хүндэтгэнэ.'],[Target,'Танд тохирсон шийдэл','Амьдралын бодит хэмнэлд нийцүүлнэ.'],[BriefcaseBusiness,'Системтэй аргачлал','Үнэлгээ, зохион байгуулалт, дадал.'],[Heart,'Хүн төвтэй хандлага','Тав тух, ойлгомжтой байдлыг эрхэмлэнэ.']].map(([Icon,t,d]:any,i:number)=>[Icon,p.sections?.benefits?.[i]?.[0]||t,p.sections?.benefits?.[i]?.[1]||d]).map(([Icon,title,desc]:any)=><div className="benefit" key={title}><Icon/><h3>{title}</h3><p>{desc}</p></div>)}</section><section className="platform-band"><div><span className="eyebrow">JURA PLATFORM</span><h2>Нэг платформ.<br/>Илүү их боломж.</h2><p>Өдөр бүрийн дадлаас суралцах ахиц хүртэл.</p><Button onClick={()=>go(user?homeFor(user):'/login')}>Кабинетад нэвтрэх <ArrowRight size={16}/></Button></div>{[[ClipboardList,'Өдрийн даалгавар','Танд оноосон ажлууд'],[GraduationCap,'Видео сургалт','Хичээл бүрийн 5 асуулт'],[Users,'Хамтын хяналт','Байгууллага, эцэг эх'],[TrendingUp,'Бодит ахиц','Гүйцэтгэл, дадал, тайлан']].map(([Icon,t,s]:any)=><div className="platform-item" key={t}><Icon/><h3>{t}</h3><p>{s}</p><div className="decor-bars" aria-hidden="true">{[25,45,35,65,55,80,95].map((h,i)=><i key={i} style={{height:h+'%'}}/>)}</div></div>)}</section></>:<><section className="benefits-strip">{benefits[key].map(([Icon,dt,ds]:any,i:number)=>[Icon,p.sections?.benefits?.[i]?.[0]||dt,p.sections?.benefits?.[i]?.[1]||ds]).map(([Icon,t,s]:any)=><div key={t}><Icon/><div><h3>{t}</h3><p>{s}</p></div></div>)}</section>{key!=='kids'&&<section className="section application-section" id="application"><div><span className="eyebrow">LET'S BEGIN</span><h2>Үйлчилгээ авах<br/>хүсэлт илгээх</h2><p className="muted">Таны хэрэгцээг эхлээд сонсоно. Бодит нөхцөлд тохирсон шийдэл, хэрэгжүүлэх алхмуудыг хамт тодорхойлно.</p><div className="assurance"><ShieldCheck/><p>Бид таны мэдээллийг хамгаалж,<br/>хүндэтгэлтэй харилцана.</p></div></div>{AppForm({type:key})}<div className="quote-photo" style={{backgroundImage:`linear-gradient(0deg,#161511b8,transparent),url('${key==='work'?img+'hero-work.webp':img+'premium-office.webp'}')`}}><p>“Эмх цэгцээс<br/>өдөр бүрийн<br/>тав тух эхэлнэ.”</p></div></section>}</>}<section className="section method" id="method"><div><span className="eyebrow">THE JURA METHOD</span><h2>{p.sections?.methodTitle||initialPages[key].sections.methodTitle}</h2></div><div className="steps">{(p.sections?.steps||initialPages[key].sections.steps).map(([t,d]:any,i:number)=><div key={t}><span className="step-number">0{i+1}</span><div><h3>{t}</h3><p>{d}</p></div></div>)}</div></section>{key==='kids'&&<section className="parent-band"><div><span className="eyebrow">PARENT MONITORING</span><h2>Нэг хүүхэд — нэг үндсэн<br/>эцэг эхийн хяналт.</h2><p>Хүүхдийн даалгавар, хичээл, шалгалт, дадлын ахицыг нэг дороос хянана. Зөвхөн тантай холбогдсон хүүхдийн мэдээлэл харагдана.</p><Button onClick={()=>go('/login')}>Миний кабинет <ArrowRight size={16}/></Button></div><img src={img+'jura-parent-family.webp'} alt="Ээж, хүүхэд хамт суралцаж байна"/></section>}</main>{Footer()}</>}
 function Login(){return <div className="login-page"><section className="login-scene" style={{backgroundImage:`linear-gradient(0deg,#12120ff2,transparent 80%),url('${img}premium-office.webp')`}}><a href="/" onClick={e=>{e.preventDefault();go('/')}}><Logo/></a><div><span className="eyebrow">SMALL CHANGES. BIG FUTURES.</span><h1>Өөртөө хөрөнгө оруул.<br/>Илүү том ирээдүйг бүтээ.</h1><p>Жижиг дадал, тогтмол үйлдэл. Таны өдөр бүрийн ахиц эндээс эхэлнэ.</p><div className="login-principles"><span><ShieldCheck/> Хувийн орон зай</span><span><Target/> Тогтвортой дадал</span><span><TrendingUp/> Бодит ахиц</span></div></div></section><section className="login-panel"><div className="login-card"><Logo light/><h2>Платформд нэвтрэх</h2><p className="muted">Админаас олгосон эрхээр өөрийн кабинетад нэвтэрнэ үү.</p><form onSubmit={onSubmit(async(e:any)=>{setBusy(true);setError('');const b=Object.fromEntries(new FormData(e.currentTarget));try{const d=await api('login',b);setUser(d.user);await refresh();go(homeFor(d.user));setToast('Тавтай морилно уу.')}catch(x:any){setError(x.message)}finally{setBusy(false)}})}><Field label="Нэвтрэх нэр" name="username" autoComplete="username" required/><Field label="Нууц үг" name="password" type="password" autoComplete="current-password" required/>{error&&<div className="inline-error" role="alert">{error}</div>}<Button className="full" disabled={busy}>{busy?'Нэвтэрч байна…':'Нэвтрэх'} <ArrowRight size={17}/></Button></form><div className="login-help"><LockKeyhole size={18}/><p>Шинэ эрх нээлгэх, нууц үг сэргээх бол админтай холбогдоно уу.</p></div><div className="role-grid">{[[Home,'PERSONAL'],[Building2,'WORK'],[GraduationCap,'KIDS'],[Heart,'PARENT'],[Users,'MANAGER'],[ShieldCheck,'ADMIN']].map(([Icon,t]:any)=><div key={t}><Icon/><span>JURA {t}</span></div>)}</div><button className="text-link" onClick={()=>go('/')}>← Үндсэн сайт руу буцах</button></div></section></div>}
 function TaskRows({ts=myTasks,owner=user?.id,readOnly=false}:any){return ts.length?<div className="task-list">{ts.map((t:any)=>{const c=completions.find((c:any)=>c.task_id===t.id&&c.date===date);return <div className={'task-row '+(c?'completed':'')} key={t.id}><button disabled={readOnly||busy} aria-label={c?'Гүйцэтгэл буцаах':'Даалгавар гүйцэтгэх'} className="task-check" onClick={()=>{if(c)perform('complete',{id:t.id,done:false}).catch(()=>{});else if(t.evidence_required)setModal({type:'complete',form:{id:t.id,note:'',evidence:''},title:t.title});else perform('complete',{id:t.id,done:true},'Даалгавар гүйцэтгэлээ.').catch(()=>{})}}>{c?<Check size={14}/>:null}</button><div className="task-detail"><strong>{t.title}</strong>{t.description&&<small>{t.description}</small>}<span>{freq[t.recurrence]}{t.evidence_required?' · Зураг шаардлагатай':''}</span>{c?.evidence&&<a href={c.evidence} target="_blank" rel="noreferrer" className="text-link">Гүйцэтгэлийн зураг <Eye size={12}/></a>}{c?.note&&<small>{c.note}</small>}</div><span className="task-time">{t.time}{t.priority==='high'&&<i className="priority-dot"/>}</span></div>})}</div>:<Empty title="Өнөөдөр даалгавар алга" text="Оноосон даалгавар энд харагдана."/>}
 function Banner({type='personal',title,sub}:any){return <div className={'dashboard-banner '+(type==='admin'||type==='company'||type==='academy'||type==='parent'?'dark':'')} style={{backgroundImage:`linear-gradient(90deg,${['admin','company','academy','parent'].includes(type)?'#171916ed 0%,#171916a0 53%,transparent':'#f7f1e6 0%,#f7f1e6cc 42%,transparent'} 90%),url('${img+(type==='parent'?'jura-parent-family.webp':type==='company'?'jura-work-team.webp':type==='admin'?'premium-office.webp':type==='academy'?'premium-office.webp':type==='kids'?'jura-kids-study.webp':'jura-personal-home.webp')}')`}}><div><span className="eyebrow">{type==='admin'?'JURA CONSULTING':type==='company'?'JURA WORK':type==='academy'?'JURA ACADEMY':type==='parent'?'GROWING TOGETHER':'YOUR PERSONAL GROWTH'}</span><h1>{title}</h1><p>{sub}</p></div><div className="banner-quote">“Сайн зуршил.<br/>Сайхан ирээдүй.”</div></div>}
 function LessonCards(){const ls=lessons.filter((l:any)=>l.status==='published'&&(filter==='all'||l.category===filter)&&l.title.toLowerCase().includes(search.toLowerCase()));return ls.length?<div className="lesson-grid">{ls.map((l:any)=>{const p=data.progress.find((p:any)=>p.lesson_id===l.id&&p.user_id===user.id);const a=data.attempts.find((a:any)=>a.lesson_id===l.id&&a.user_id===user.id&&a.passed);return <article className="lesson-card" key={l.id}><button className="lesson-image" onClick={()=>go('/academy/'+l.id)}><img src={l.thumbnail} alt={l.title}/><span className="video-play"><Play size={20}/></span><Badge>{l.category.toUpperCase()}</Badge></button><div className="lesson-copy"><small>{l.module}</small><h3>{l.title}</h3><p>{l.description}</p><div className="lesson-meta"><span><Clock size={13}/>{Math.ceil(l.duration/60)} мин</span><span><ClipboardList size={13}/>5 асуулт</span></div><Progress value={a?100:p?Math.min(95,Math.round(p.seconds/l.duration*100)):0}/><div className="lesson-bottom"><span>{a?'Тэнцсэн':p?.watched?'Шалгалтад бэлэн':p?'Үргэлжлүүлэх':'Эхлээгүй'}</span><button aria-label="Хичээл нээх" onClick={()=>go('/academy/'+l.id)}><ArrowRight size={16}/></button></div></div></article>})}</div>:<Empty title="Нийтэлсэн хичээл алга" text="Админ видео болон 5 асуулттай хичээл нийтлэхэд харагдана." action={user.role==='admin'?<Button onClick={()=>openLesson()}>Хичээл нэмэх <Plus size={15}/></Button>:null}/>}
 function PersonalDash(){const myProgress=data.progress.filter((p:any)=>p.user_id===user.id&&p.watched).length;return <><Banner type={user.role} title={`Сайн байна уу, ${user.name}!`} sub="Өдөр бүрийн жижиг алхам тогтвортой өөрчлөлт бүтээнэ."/><div className="stats"><Stat icon={ClipboardList} label="Өнөөдрийн даалгавар" value={`${myDone.length}/${myTasks.length}`} pct={myTasks.length?Math.round(myDone.length/myTasks.length*100):0}/><Stat icon={Flame} label="Дараалсан дадал" value={streak(user.id)+' өдөр'} sub="Гүйцэтгэлтэй дараалсан хоног"/><Stat icon={GraduationCap} label="Үзсэн хичээл" value={myProgress} sub="Видео бүрэн үзсэн"/><Stat icon={CheckCheck} label="Өгсөн шалгалт" value={data.attempts.filter((a:any)=>a.user_id===user.id).length} sub="Хадгалсан оролдлого"/></div><div className="dashboard-grid"><section className="panel"><div className="panel-title"><h2>Өнөөдрийн To-Do</h2><Badge>{date}</Badge></div>{TaskRows({})}<button className="text-link" onClick={()=>go('/tasks')}>Бүх даалгавар <ArrowRight size={14}/></button></section><section className="feature-photo" style={{backgroundImage:`linear-gradient(90deg,#191810df,transparent),url('${img}jura-personal-home.webp')`}}><span className="eyebrow">ӨДӨР БҮР ӨӨРТӨӨ</span><h2>Өөртөө цаг гарга.<br/>Эмх цэгцтэй амьдар.</h2><p>Таны ахиц. Таны амьдралын хэмнэл.</p><Button onClick={()=>go('/academy')}>Хичээлээ үргэлжлүүлэх <ArrowRight size={15}/></Button></section><section className="panel"><h2>7 хоногийн гүйцэтгэл</h2><Trend completions={completions.filter((c:any)=>c.user_id===user.id)}/></section><section className="panel learning-summary"><h2>Миний сургалтын ахиц</h2><div className="ring" style={{'--p':lessons.length?Math.round(myProgress/lessons.length*100):0} as any}><b>{lessons.length?Math.round(myProgress/lessons.length*100):0}%</b></div><div><p>Бүрэн үзсэн <strong>{myProgress}</strong></p><p>Боломжтой хичээл <strong>{lessons.filter((l:any)=>l.status==='published').length}</strong></p><button className="text-link" onClick={()=>go('/academy')}>Бүх хичээлийг харах →</button></div></section></div></>}
 function HeaderAction({title,sub,children}:any){return <div className="page-heading"><div><span className="eyebrow">JURA PLATFORM</span><h1>{title}</h1>{sub&&<p>{sub}</p>}</div><div className="heading-actions">{children}</div></div>}
 function PeopleTable({manager=false}:any){const rows=list.filter((u:any)=>(!manager||u.role==='work')&&(filter==='all'||u.role===filter)&&`${u.name} ${u.username} ${u.email}`.toLowerCase().includes(search.toLowerCase()));return <div className="table-wrap"><table><thead><tr><th>Хэрэглэгч</th><th>Эрх</th><th>Байгууллага / Холбоос</th><th>Өнөөдрийн гүйцэтгэл</th><th>Төлөв</th><th/></tr></thead><tbody>{rows.map((u:any)=>{const c=calc(u.id);return <tr key={u.id}><td><div className="person-cell"><span className="avatar">{u.name.charAt(0)}</span><div><strong>{u.name}</strong><small>{u.username}</small></div></div></td><td>{roleNames[u.role]}</td><td>{data.organizations.find((o:any)=>o.id===u.organization_id)?.name||list.find((p:any)=>p.id===u.parent_id)?.name||'—'}</td><td><div className="table-progress"><Progress value={c.percent}/><span>{c.done}/{c.total}</span></div></td><td><Badge tone={u.status==='active'?'green':''}>{u.status==='active'?'Идэвхтэй':'Түдгэлзсэн'}</Badge></td><td>{!manager?<button className="icon-btn" aria-label="Хэрэглэгч засах" onClick={()=>openUser(u)}><Pencil size={15}/></button>:<button className="text-link" onClick={()=>{openTask();setModal((m:any)=>({...m,form:{...m.form,user_id:u.id}}))}}>Оноох →</button>}</td></tr>})}</tbody></table>{!rows.length&&<Empty title="Хэрэглэгч олдсонгүй"/>}</div>}
 function AdminHome(){const c=calc();return <><Banner type="admin" title="JURA Control Center" sub="Платформын агуулга, хэрэглэгч, сургалт, гүйцэтгэл — нэг цонхноос."/><div className="stats"><Stat icon={Users} label="Нийт хэрэглэгч" value={list.length} sub="Бүртгэлтэй эрхүүд"/><Stat icon={Building2} label="Идэвхтэй байгууллага" value={data.organizations.length} sub="Байгууллагын бүртгэл"/><Stat icon={GraduationCap} label="Нийтэлсэн сургалт" value={lessons.filter((l:any)=>l.status==='published').length} sub={`${lessons.filter((l:any)=>l.status==='draft').length} ноорог`} /><Stat icon={ClipboardList} label="Өдрийн To-Do гүйцэтгэл" value={c.percent+'%'} sub={`${c.done} / ${c.total} даалгавар`}/></div><div className="quick-tabs">{[[ImageIcon,'Вэбсайт CMS','/admin/cms'],[Users,'Хэрэглэгчийн удирдлага','/admin/users'],[ClipboardList,'To-Do менежер','/admin/tasks'],[BookOpen,'Academy LMS','/admin/academy'],[TrendingUp,'Аналитик тайлан','/admin/reports']].map(([Icon,t,p]:any)=><button key={t} onClick={()=>go(p)}><Icon size={17}/>{t}</button>)}</div><div className="admin-overview-grid"><section className="panel"><div className="panel-title"><h2>Вэбсайт CMS засвар</h2><button className="text-link" onClick={()=>go('/admin/cms')}>Бүгдийг засах →</button></div><img className="cms-preview-image" src={pages.home.image} alt="Нүүр хуудасны үндсэн зураг"/><span className="eyebrow">ҮНДСЭН НҮҮР</span><h3 className="serif">{pages.home.title}</h3><p className="muted">{pages.home.description}</p><Button onClick={()=>go('/admin/cms')}>Агуулга засах <Pencil size={14}/></Button></section><section className="panel"><div className="panel-title"><h2>To-Do оноолт</h2><ClipboardList size={18}/></div><p className="muted">Хэрэглэгч тус бүрд нэг удаагийн болон давтамжтай даалгавар онооно.</p><div className="mini-count"><strong>{tasks.filter((t:any)=>t.active).length}</strong><span>идэвхтэй даалгавар</span></div><Button className="full" onClick={()=>openTask()}>Даалгавар нэмэх <Plus size={15}/></Button><hr/><h3>Шинэ үйлчилгээний хүсэлт</h3><div className="mini-count"><strong>{data.applications.filter((a:any)=>a.status==='Шинэ').length}</strong><span>хариу хүлээж байна</span></div><button className="text-link" onClick={()=>go('/admin/applications')}>Хүсэлтүүдийг харах →</button></section><section className="panel"><div className="panel-title"><h2>Academy хичээл үүсгэх</h2><BookOpen size={18}/></div><p className="muted">Видео, тайлбар, яг 5 асуулттай хичээл.</p><img className="course-preview" src={img+'jura-academy-learner.webp'} alt="Сургалтын орчин"/><div className="three-mini"><div><strong>{lessons.length}</strong><span>Нийт хичээл</span></div><div><strong>{data.attempts.length}</strong><span>Шалгалт</span></div><div><strong>{data.progress.filter((p:any)=>p.watched).length}</strong><span>Видео үзэлт</span></div></div><Button className="full" onClick={()=>openLesson()}>Хичээл нэмэх <Plus size={15}/></Button></section><section className="panel"><h2>Гүйцэтгэлийн хандлага</h2><Trend completions={completions}/></section><section className="panel"><h2>Хэрэглэгчийн бүтэц</h2><div className="role-distribution">{Object.keys(roleNames).map((r,i)=>{const n=list.filter((u:any)=>u.role===r).length;return <div key={r}><span className={'legend-dot color-'+i}/><span>{roleNames[r]}</span><strong>{n}</strong></div>})}</div></section><section className="panel"><h2>Сүүлийн үйлдлүүд</h2><div className="activity-list">{data.audit.slice(0,5).map((a:any)=><div key={a.id}><span className="activity-dot"/><div><strong>{actionName(a.action)}</strong><small>{a.user_name||'Систем'} · {fmt(a.created_at)}</small></div></div>)}</div></section></div></>}
 function actionName(a:string){return ({login:'Нэвтэрсэн',user_create:'Хэрэглэгч үүсгэсэн',user_update:'Хэрэглэгч шинэчилсэн',organization_save:'Байгууллага хадгалсан',task_save:'Даалгавар хадгалсан',lesson_save:'Хичээл хадгалсан',cms_publish:'Агуулга нийтэлсэн',cms_draft:'Ноорог хадгалсан',settings_save:'Тохиргоо шинэчилсэн',file_upload:'Файл байршуулсан',export:'Мэдээлэл экспортолсон',login_failed:'Амжилтгүй нэвтрэлт',applicationStatus:'Хүсэлтийн төлөв сольсон',note:'Тэмдэглэл нэмсэн','5s_templates':'5S загвар оноосон',cms_rollback:'Агуулга сэргээсэн',password_change:'Нууц үг сольсон',email_dispatch:'Имэйл илгээсэн',reminders_queue:'Сануулга бэлтгэсэн'} as any)[a]||a}
 function AdminUsers(){return <><HeaderAction title="Хэрэглэгчийн удирдлага" sub="Эрхийг зөвхөн админ үүсгэж, өөрчилнө."><Button className="secondary" onClick={()=>download('users')}><Download size={15}/> Экспорт</Button><Button onClick={()=>openUser()}><Plus size={16}/> Хэрэглэгч нэмэх</Button></HeaderAction><div className="panel"><div className="toolbar">{SearchBox()}<select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Бүх эрх</option>{Object.entries(roleNames).map(([k,v]:any)=><option value={k} key={k}>{v}</option>)}</select></div>{PeopleTable({})}</div></>}
 function SearchBox(){return <div className="search-box"><Search size={16}/><input placeholder="Хайх…" aria-label="Хайх" value={search} onChange={e=>setSearch(e.target.value)}/></div>}
 function Organizations(){return <><HeaderAction title="Байгууллагууд" sub="Байгууллага бүрийн ажилтан, даалгавар тусгаарлагдана."><Button onClick={()=>setModal({type:'organization',form:{name:''}})}><Plus size={16}/> Байгууллага нэмэх</Button></HeaderAction><div className="org-grid">{data.organizations.map((o:any)=>{const members=list.filter((u:any)=>u.organization_id===o.id);const ts=tasks.filter((t:any)=>t.organization_id===o.id);return <article className="panel" key={o.id}><div className="org-icon"><Building2/></div><h2>{o.name}</h2><p className="muted">{members.length} хэрэглэгч · {ts.filter((t:any)=>t.active).length} идэвхтэй даалгавар</p><div className="panel-title"><Badge>{fmt(o.created_at)}</Badge><button className="icon-btn" onClick={()=>setModal({type:'organization',form:o})} aria-label="Байгууллага засах"><Pencil size={16}/></button></div></article>})}</div>{!data.organizations.length&&<div className="panel"><Empty title="Байгууллага нэмээгүй байна" text="Эхлээд байгууллага үүсгээд удирдлага, ажилтныг холбоно уу."/></div>}</>}
 function Applications(){const rows=data.applications.filter((a:any)=>(filter==='all'||a.status===filter)&&`${a.name} ${a.phone} ${a.email} ${a.type}`.toLowerCase().includes(search.toLowerCase()));return <><HeaderAction title="Үйлчилгээний хүсэлтүүд" sub="Сайтаас ирсэн PERSONAL, WORK, KIDS хүсэлтүүд."><Button className="secondary" onClick={()=>download('applications')}><Download size={15}/> CSV татах</Button></HeaderAction><div className="panel"><div className="toolbar">{SearchBox()}<select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Бүх төлөв</option>{statuses.map(s=><option key={s}>{s}</option>)}</select></div><div className="table-wrap"><table><thead><tr><th>Хүсэлт гаргагч</th><th>Үйлчилгээ</th><th>Холбоо барих</th><th>Төлөв</th><th>Ирсэн огноо</th><th/></tr></thead><tbody>{rows.map((a:any)=><tr key={a.id}><td><strong>{a.name}</strong></td><td><Badge>{a.type.toUpperCase()}</Badge></td><td>{a.phone}<small>{a.email}</small></td><td><Badge tone={a.status==='Шинэ'?'gold':''}>{a.status}</Badge></td><td>{fmt(a.created_at)}</td><td><button className="text-link" onClick={()=>setModal({type:'application',form:{...a,parsed:JSON.parse(a.data)},note:''})}>Дэлгэрэнгүй →</button></td></tr>)}</tbody></table>{!rows.length&&<Empty title="Хүсэлт хараахан ирээгүй байна" text="Сайтын хүсэлтийн формыг бөглөхөд энд хадгалагдана."/>}</div></div></>}
 function TasksAdmin(){const ts=tasks.filter((t:any)=>(filter==='all'||(filter==='active'?t.active:!t.active))&&`${t.title} ${list.find((u:any)=>u.id===t.user_id)?.name}`.toLowerCase().includes(search.toLowerCase()));return <><HeaderAction title="To-Do менежер" sub="Оноолт, давтамж, хугацаа, гүйцэтгэлийн баталгааг удирдана."><Button className="secondary" onClick={()=>download('tasks')}><Download size={15}/> Экспорт</Button><Button onClick={()=>openTask()}><Plus size={15}/> Даалгавар нэмэх</Button></HeaderAction><div className="panel"><div className="toolbar">{SearchBox()}<select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Бүх даалгавар</option><option value="active">Идэвхтэй</option><option value="inactive">Идэвхгүй</option></select></div><div className="table-wrap"><table><thead><tr><th>Даалгавар</th><th>Хэрэглэгч</th><th>Огноо / Давтамж</th><th>Хугацаа</th><th>Төлөв</th><th/></tr></thead><tbody>{ts.map((t:any)=><tr key={t.id}><td><strong>{t.title}</strong><small>{t.evidence_required?'Зурагтай баталгаа':''}</small></td><td>{list.find((u:any)=>u.id===t.user_id)?.name||'—'}</td><td>{t.date}<small>{freq[t.recurrence]}</small></td><td>{t.time}</td><td><Badge tone={t.active?'green':''}>{t.active?'Идэвхтэй':'Идэвхгүй'}</Badge></td><td><button className="icon-btn" aria-label="Даалгавар засах" onClick={()=>openTask(t)}><Pencil size={15}/></button></td></tr>)}</tbody></table>{!ts.length&&<Empty title="Даалгавар нэмээгүй байна" text="Хэрэглэгч сонгон эхний даалгавраа онооно уу."/>}</div></div><div className="panel work-template"><div><span className="eyebrow">WORK MASTER PLAYBOOK</span><h2>Өглөө 09:00 · Орой 17:40</h2><p>WORK ажилтанд стандарт 3 дадлыг нэг дор онооно.</p></div><form className="inline-form" onSubmit={onSubmit(async(e:any)=>{const f=new FormData(e.currentTarget);await perform('workTemplates',{user_id:f.get('user_id')},'5S дадлуудыг оноолоо.')} )}><select name="user_id" required><option value="">Ажилтан сонгох</option>{list.filter((u:any)=>u.role==='work').map((u:any)=><option key={u.id} value={u.id}>{u.name}</option>)}</select><Button disabled={busy}>5S загвар оноох</Button></form></div></>}
 function AcademyAdmin(){return <><HeaderAction title="Academy LMS" sub="Зөвхөн видео, яг 5 бүрэн асуулттай хичээлийг нийтэлнэ."><Button onClick={()=>openLesson()}><Plus size={16}/> Хичээл нэмэх</Button></HeaderAction><div className="panel"><div className="toolbar">{SearchBox()}<Badge>{lessons.length} хичээл</Badge></div><div className="table-wrap"><table><thead><tr><th>Хичээл</th><th>Ангилал</th><th>Хугацаа</th><th>Төлөв</th><th>Асуулт</th><th/></tr></thead><tbody>{lessons.filter((l:any)=>l.title.toLowerCase().includes(search.toLowerCase())).map((l:any)=><tr key={l.id}><td><div className="person-cell"><img className="table-thumbnail" src={l.thumbnail} alt=""/><div><strong>{l.title}</strong><small>{l.module}</small></div></div></td><td><Badge>{l.category.toUpperCase()}</Badge></td><td>{Math.ceil(l.duration/60)} мин</td><td><Badge tone={l.status==='published'?'green':''}>{({draft:'Ноорог',published:'Нийтэлсэн',archived:'Архивласан'} as any)[l.status]}</Badge></td><td>{l.questions.length}/5</td><td><button className="icon-btn" aria-label="Хичээл засах" onClick={()=>openLesson(l)}><Pencil size={16}/></button></td></tr>)}</tbody></table>{!lessons.length&&<Empty title="Анхны хичээлээ нэмээрэй" text="Видео байхгүй хичээлийг ноорог болгон хадгалж болно."/>}</div></div></>}
 function CMS(){return <><HeaderAction title="Вэбсайт CMS" sub="Ноорог → урьдчилж харах → нийтлэх. Өмнөх хувилбарыг сэргээж болно."><Button className="secondary" onClick={()=>setPreview(!preview)}><Eye size={15}/>{preview?'Засварлах':'Урьдчилж харах'}</Button></HeaderAction><div className="cms-layout"><div className="panel"><div className="toolbar"><select value={cmsPage} onChange={e=>setCmsPage(e.target.value)}>{Object.keys(initialPages).map(p=><option key={p} value={p}>{p==='home'?'Үндсэн нүүр':'JURA '+p.toUpperCase()}</option>)}</select><Badge>Hero агуулга</Badge></div>{preview?<div className="cms-live-preview" style={{backgroundImage:`linear-gradient(90deg,#161512e8,transparent),url('${cmsForm.image}')`}}><span className="eyebrow">{cmsForm.eyebrow}</span><h2>{cmsForm.title}</h2><p>{cmsForm.description}</p><Button>{cmsForm.cta}</Button></div>:<><Field label="Дээд жижиг бичвэр"><input value={cmsForm.eyebrow} onChange={e=>setCmsForm({...cmsForm,eyebrow:e.target.value})}/></Field><Field label="Үндсэн гарчиг"><textarea value={cmsForm.title} onChange={e=>setCmsForm({...cmsForm,title:e.target.value})}/></Field><Field label="Тайлбар"><textarea value={cmsForm.description} onChange={e=>setCmsForm({...cmsForm,description:e.target.value})}/></Field><Field label="Товчны бичвэр"><input value={cmsForm.cta} onChange={e=>setCmsForm({...cmsForm,cta:e.target.value})}/></Field><Field label="Үндсэн зургийн зам"><input value={cmsForm.image} onChange={e=>setCmsForm({...cmsForm,image:e.target.value})}/></Field><label className="upload-zone"><Upload size={19}/><span>Шинэ зураг байршуулж сонгох</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={async e=>{if(e.target.files?.[0])try{const url=await upload(e.target.files[0]);setCmsForm({...cmsForm,image:url});await refresh()}catch{}}}/></label></>}<details className="cms-section-editor"><summary>Бусад хэсгийн агуулга засах</summary><Field label="Аргачлалын хэсгийн гарчиг"><input value={cmsForm.sections?.methodTitle||''} onChange={e=>setCmsForm({...cmsForm,sections:{...cmsForm.sections,methodTitle:e.target.value}})}/></Field>{['benefits','steps'].map(group=><div key={group}><h3>{group==='benefits'?'Давуу талууд':'Аргачлалын алхмууд'}</h3>{(cmsForm.sections?.[group]||[]).map((row:any,i:number)=><div className="question-editor" key={i}>{row.map((text:string,j:number)=><Field key={j} label={`${i+1}. ${j===0?'Гарчиг':'Тайлбар'}`} value={text} onChange={(e:any)=>{const rows=cmsForm.sections[group].map((r:any,k:number)=>k===i?r.map((v:string,n:number)=>n===j?e.target.value:v):r);setCmsForm({...cmsForm,sections:{...cmsForm.sections,[group]:rows}})}}/>)}</div>)}</div>)}</details><div className="form-actions"><Button className="secondary" disabled={busy} onClick={()=>perform('cms',{page:cmsPage,content:cmsForm,publish:false},'Ноорог хадгаллаа.').catch(()=>{})}>Ноорог хадгалах</Button><Button disabled={busy} onClick={()=>perform('cms',{page:cmsPage,content:cmsForm,publish:true},'Агуулга нийтлэгдлээ.').catch(()=>{})}>Нийтлэх <ArrowUpRight size={15}/></Button></div></div><div><section className="panel"><h2>Хувилбарын түүх</h2><p className="muted">Нийтлэх бүрд өмнөх агуулга хадгалагдана.</p>{data.versions.filter((v:any)=>v.page_id===cmsPage).map((v:any)=><div className="version-row" key={v.id}><div><History size={16}/><small>{fmt(v.created_at)}</small></div><button className="text-link" onClick={()=>perform('rollback',{id:v.id},'Өмнөх агуулгыг сэргээлээ.').catch(()=>{})}>Сэргээх</button></div>)}{!data.versions.some((v:any)=>v.page_id===cmsPage)&&<p className="muted">Өмнөх хувилбар алга.</p>}</section><section className="panel"><h2>Медиа сан</h2><div className="media-grid">{data.files.filter((f:any)=>f.kind==='image').map((f:any)=><button key={f.id} onClick={()=>setCmsForm({...cmsForm,image:'/api/files/'+f.id})}><img src={'/api/files/'+f.id} alt={f.name}/></button>)}</div>{!data.files.some((f:any)=>f.kind==='image')&&<p className="muted">Шинэ байршуулсан зураг энд харагдана.</p>}</section></div></div></>}
 function Reports(){const c=calc();return <><HeaderAction title="Ахиц ба тайлан" sub="Зөвхөн системд хадгалсан гүйцэтгэлээс тооцно."><Button className="secondary" onClick={()=>window.print()}><FileText size={15}/> PDF / Хэвлэх</Button><Button onClick={()=>download('completions')}><Download size={15}/> Гүйцэтгэл татах</Button></HeaderAction><div className="stats"><Stat label="Өдрийн гүйцэтгэл" value={c.percent+'%'} sub={c.done+'/'+c.total} icon={CheckCheck}/><Stat label="Нийт гүйцэтгэл" value={completions.length} icon={ClipboardList}/><Stat label="Шалгалтын оролдлого" value={data.attempts.length} icon={GraduationCap}/><Stat label="Тэнцсэн оролдлого" value={data.attempts.filter((a:any)=>a.passed).length} icon={CheckCircle2}/></div><div className="dashboard-grid"><section className="panel"><h2>Сүүлийн 7 хоног</h2><Trend completions={completions}/></section><section className="panel"><h2>Зурагтай гүйцэтгэл · Visual Audit</h2><div className="evidence-grid">{completions.filter((c:any)=>c.evidence).slice(0,12).map((c:any)=><a key={c.id} href={c.evidence} target="_blank" rel="noreferrer"><img src={c.evidence} alt="Гүйцэтгэлийн баталгаажуулалт"/><small>{list.find((u:any)=>u.id===c.user_id)?.name} · {c.date}</small></a>)}</div>{!completions.some((c:any)=>c.evidence)&&<p className="muted">Зурагтай баталгаажуулалт хараахан алга.</p>}</section></div><section className="panel"><h2>Хэрэглэгчийн гүйцэтгэл</h2>{PeopleTable({manager:user.role==='manager'})}</section>{user.role==='admin'&&<section className="panel"><div className="panel-title"><h2>Аудитын түүх</h2><Button className="secondary compact" onClick={()=>download('audit_logs')}><Download size={13}/> CSV</Button></div><div className="table-wrap"><table><thead><tr><th>Хэзээ</th><th>Хэрэглэгч</th><th>Үйлдэл</th><th>Дэлгэрэнгүй</th></tr></thead><tbody>{data.audit.map((a:any)=><tr key={a.id}><td>{fmt(a.created_at)}</td><td>{a.user_name||'Систем'}</td><td>{actionName(a.action)}</td><td>{a.detail||'—'}</td></tr>)}</tbody></table></div></section>}</>}
 function Notifications(){return <><HeaderAction title="Мэдэгдэл, имэйл" sub="Хүсэлтийн мэдэгдэл болон өдөр тутмын даалгаврын сануулга."><Button className="secondary" disabled={busy} onClick={()=>perform('reminders',{},'Өнөөдрийн сануулгуудыг бэлтгэлээ.').catch(()=>{})}><Bell size={15}/> Сануулга бэлтгэх</Button><Button disabled={busy||!data.emailConfigured} onClick={()=>perform('dispatch',{},'Имэйл илгээх оролдлого дууслаа.').catch(()=>{})}><Send size={15}/> Хүлээгдэж буйг илгээх</Button></HeaderAction><div className={'notice '+(data.emailConfigured?'success':'')}><Mail size={19}/><div><strong>{data.emailConfigured?'Имэйл үйлчилгээ холбогдсон':'Имэйл үйлчилгээний тохиргоо хүлээгдэж байна'}</strong><p>{data.emailConfigured?'RESEND үйлчилгээ рүү бодитоор илгээнэ.':'RESEND_API_KEY, баталгаажсан EMAIL_FROM тохируулсны дараа илгээх боломж нээгдэнэ. Бэлтгэсэн мэдэгдэл илгээгдсэнд тооцогдохгүй.'}</p></div></div><div className="panel"><h2>Имэйлийн бүртгэл</h2><div className="table-wrap"><table><thead><tr><th>Сэдэв</th><th>Хүлээн авагч</th><th>Төлөв</th><th>Оролдлого</th><th>Огноо</th></tr></thead><tbody>{data.outbox.map((x:any)=><tr key={x.id}><td><strong>{x.subject}</strong>{x.error&&<small className="danger-text">{x.error}</small>}</td><td>{x.recipient}</td><td><Badge tone={x.status==='sent'?'green':''}>{({queued:'Хүлээгдэж байна',sent:'Илгээсэн',failed:'Амжилтгүй'} as any)[x.status]}</Badge></td><td>{x.attempts}</td><td>{fmt(x.sent_at||x.created_at)}</td></tr>)}</tbody></table>{!data.outbox.length&&<Empty title="Имэйл мэдэгдэл алга"/>}</div></div></>}
 function SettingsPage(){return <><HeaderAction title="Тохиргоо" sub="Сургалт, холбоо барих мэдээлэл болон дансны аюулгүй байдал."/>{user.role==='admin'&&<form className="panel" onSubmit={onSubmit(async(e:any)=>{const settings=Object.fromEntries(new FormData(e.currentTarget));await perform('settings',{settings})})}><h2>Платформын тохиргоо</h2><p className="muted">Автомат шалгалт цаг тутам ажиллаж, тохируулсан цагаас хойш өдрийн сануулгыг давхардуулахгүй бэлтгэнэ.</p><div className="fields"><Field label="Шалгалтын тэнцэх зөв хариулт (1–5)" name="passMark" type="number" min="1" max="5" defaultValue={data.settings.passMark} required/><Field label="Оролдлогын хязгаар (0 = хязгааргүй)" name="retryLimit" type="number" min="0" max="100" defaultValue={data.settings.retryLimit} required/><Field label="Админы мэдэгдлийн имэйл" name="adminEmail" type="email" defaultValue={data.settings.adminEmail} required/><Field label="Өглөөний сануулгын эхлэх цаг · Улаанбаатар" name="reminderTime" type="time" defaultValue={data.settings.reminderTime} required/><Field label="Холбоо барих утас" name="contactPhone" defaultValue={data.settings.contactPhone} required/><Field label="Холбоо барих имэйл" name="contactEmail" type="email" defaultValue={data.settings.contactEmail} required/></div><Field label="Хаяг" name="contactAddress" defaultValue={data.settings.contactAddress}/><div className="form-actions"><Button disabled={busy}>Тохиргоо хадгалах</Button></div></form>}<form className="panel password-panel" onSubmit={onSubmit(async(e:any)=>{const f=e.currentTarget;const d:any=Object.fromEntries(new FormData(f));if(d.password!==d.confirm){setError('Шинэ нууц үг давталттайгаа тохирохгүй.');return}setBusy(true);try{await api('password',d);setUser(null);setData(null);go('/login');setToast('Нууц үг солигдлоо. Шинэ нууц үгээр нэвтэрнэ үү.')}catch(e:any){setError(e.message)}finally{setBusy(false)}})}><h2><LockKeyhole size={18}/> Нууц үг солих</h2><p className="muted">Нууц үг сольсноор бүх төхөөрөмжийн нэвтрэлт дуусна.</p><Field label="Одоогийн нууц үг" type="password" name="current" autoComplete="current-password" required/><div className="fields"><Field label="Шинэ нууц үг · 10+ тэмдэгт" type="password" name="password" minLength="10" autoComplete="new-password" required/><Field label="Шинэ нууц үг давтах" type="password" name="confirm" minLength="10" autoComplete="new-password" required/></div><Button disabled={busy}>Нууц үг шинэчлэх</Button></form></>}
 function Company(){const c=calc();return <><Banner type="company" title="Байгууллагын удирдлага" sub={data.organizations[0]?.name||'Хүмүүсээ хөгжүүлж, систем бүтээж, бүтээмжтэй багийг дэмжье.'}/><div className="stats"><Stat label="Нийт ажилтан" value={list.filter((u:any)=>u.role==='work').length} icon={Users}/><Stat label="Өдрийн гүйцэтгэл" value={c.percent+'%'} pct={c.percent} icon={Target}/><Stat label="Идэвхтэй To-Do" value={tasks.filter((t:any)=>t.active).length} icon={ClipboardList}/><Stat label="Шалгалтын оролдлого" value={data.attempts.length} icon={GraduationCap}/></div><div className="dashboard-grid"><section className="panel"><h2>Багийн гүйцэтгэл</h2><Trend completions={completions}/></section><section className="feature-photo" style={{backgroundImage:`linear-gradient(90deg,#171713d9,transparent),url('${img}jura-work-team.webp')`}}><h2>Жижиг өөрчлөлт.<br/>Тогтвортой бүтээмж.</h2><Button onClick={()=>openTask()}>Даалгавар оноох <Plus size={15}/></Button></section></div><section className="panel"><div className="panel-title"><h2>Ажилтны гүйцэтгэл</h2><Button onClick={()=>openTask()}><Plus size={15}/> Оноолт</Button></div>{PeopleTable({manager:true})}</section></>}
 function Parent(){const c=targetChild?calc(targetChild.id):{total:0,done:0,percent:0};const cp=data.progress.filter((p:any)=>p.user_id===targetChild?.id&&p.watched);const ca=data.attempts.filter((a:any)=>a.user_id===targetChild?.id);return <><Banner type="parent" title="Хүүхдийнхээ ахицыг үргэлж хамтдаа хянаарай." sub="Жижиг дадал. Гэр бүлийн дэмжлэг. Бие даасан ирээдүй."/>{!targetChild?<div className="panel"><Empty title="Холбогдсон хүүхэд алга" text="Админ хүүхдийн бүртгэлийг баталгаажсан зөвшөөрлөөр холбоно."/></div>:<><div className="child-selector"><span className="avatar">{targetChild.name.charAt(0)}</span><select aria-label="Хүүхэд сонгох" value={targetChild.id} onChange={e=>setSelectedChild(e.target.value)}>{list.filter((x:any)=>x.role==='kids').map((x:any)=><option key={x.id} value={x.id}>{x.name}</option>)}</select><Badge tone="green"><ShieldCheck size={13}/> Холбоос баталгаажсан</Badge></div><div className="stats"><Stat label="Өдрийн даалгавар" value={c.done+'/'+c.total} pct={c.percent} icon={ClipboardList}/><Stat label="Үзсэн хичээл" value={cp.length} icon={GraduationCap}/><Stat label="Тэнцсэн шалгалт" value={ca.filter((a:any)=>a.passed).length} icon={CheckCheck}/><Stat label="Тууштай дадал" value={streak(targetChild.id)+' өдөр'} icon={Flame}/></div><div className="dashboard-grid"><section className="panel"><h2>Өнөөдрийн даалгавар</h2>{TaskRows({ts:tasks.filter((t:any)=>t.user_id===targetChild.id&&due(t,date)),owner:targetChild.id,readOnly:true})}</section><section className="panel"><h2>Суралцах ахиц</h2>{cp.length?cp.map((p:any)=><div className="task-row" key={p.id}><BookOpen size={19}/><div><strong>{lessons.find((l:any)=>l.id===p.lesson_id)?.title||'Хүүхдийн хичээл'}</strong><Progress value={100}/></div><Badge tone="green">Үзсэн</Badge></div>):<Empty title="Үзсэн хичээл алга"/>}</section><section className="panel"><h2>7 хоногийн гүйцэтгэл</h2><Trend completions={completions.filter((c:any)=>c.user_id===targetChild.id)}/></section><section className="panel"><h2>Шалгалтын дүн</h2>{ca.length?ca.map((a:any)=><div className="version-row" key={a.id}><span>{fmt(a.created_at)}</span><Badge tone={a.passed?'green':''}>{a.score}/5 · {a.passed?'Тэнцсэн':'Дахин суралцах'}</Badge></div>):<p className="muted">Шалгалтын оролдлого алга.</p>}</section></div></>}</>}
 async function tick(force=false){if(!lesson||!videoRef.current||videoRef.current.paused&&!force)return;const n=Date.now();if(!force&&n-lastTick.current<9000)return;lastTick.current=n;try{const d=await api('watch',{id:lesson.lesson.id,position:videoRef.current.currentTime});if(d.watched&&!lesson.progress?.watched){const r=await fetch('/api/jura?view=lesson&id='+lesson.lesson.id);setLesson(await r.json());setToast('Видео дууслаа. 5 асуулттай шалгалт нээгдлээ.')}}catch(e:any){setError(e.message)}}
 function LessonView(){if(!lesson)return <div className="loading-state">Хичээл уншиж байна…</div>;const l=lesson.lesson;return <><HeaderAction title={l.title} sub={l.module}><Button className="secondary" onClick={()=>go('/academy')}>← Бүх хичээл</Button></HeaderAction><div className="lesson-layout"><section className="panel video-panel">{l.video?<video key={l.id} ref={videoRef} src={l.video} poster={l.thumbnail} controls controlsList="nodownload" onPlay={()=>tick(true)} onTimeUpdate={()=>tick()} onEnded={()=>tick(true)}/>:<div className="video-empty"><img src={l.thumbnail} alt=""/><span>Видео хараахан нэмээгүй байна.</span></div>}<h2>{l.title}</h2><p className="muted">{l.description}</p><div className="lesson-meta"><span><Clock size={15}/>{Math.ceil(l.duration/60)} минут</span><span><ClipboardList size={15}/>Яг 5 асуулт</span><Badge>{l.category.toUpperCase()}</Badge></div></section><section className="panel"><h2>Сургалтын дараалал</h2><ol className="lesson-steps"><li><span>01</span><div><strong>Видео хичээл</strong><p>Видеог эхнээс нь бүрэн үзнэ.</p></div></li><li><span>02</span><div><strong>5 асуулттай шалгалт</strong><p>Бүх асуултад хариулна.</p></div></li><li><span>03</span><div><strong>Үр дүн, ахиц</strong><p>Оноо серверт хадгалагдана.</p></div></li></ol><Badge tone={lesson.progress?.watched?'green':''}>{lesson.progress?.watched?'Видео бүрэн үзсэн':'Видео үзэж дуусгана уу'}</Badge><hr/><h3>Өмнөх оролдлого</h3>{lesson.attempts.map((a:any)=><div className="version-row" key={a.id}><small>{fmt(a.created_at)}</small><Badge tone={a.passed?'green':''}>{a.score}/5</Badge></div>)}{!lesson.attempts.length&&<p className="muted">Оролдлого алга.</p>}</section></div>{lesson.progress?.watched?<section className="panel quiz-panel"><span className="eyebrow">KNOWLEDGE CHECK · 5 QUESTIONS</span><h2>Сурснаа бататгая</h2>{result?<div className="quiz-result"><div className="ring" style={{'--p':result.score*20} as any}><b>{result.score}/5</b></div><h2>{result.passed?'Баяр хүргэе, тэнцлээ!':'Дахин бататгаад үзээрэй.'}</h2><p>Таны үр дүн хадгалагдсан.</p><Button onClick={()=>{setResult(null);setAnswers({});go('/academy')}}>Сургалтууд руу буцах</Button></div>:<form onSubmit={onSubmit(async()=>{const a=Array.from({length:5},(_,i)=>Number(answers[i]));if(a.some(x=>!Number.isInteger(x))){setError('Бүх асуултад хариулна уу.');return}setBusy(true);try{const r=await api('quiz',{id:l.id,answers:a});setResult(r);await refresh()}catch(e:any){setError(e.message)}finally{setBusy(false)}})}>{lesson.questions.map((q:any,i:number)=><fieldset key={i}><legend>{i+1}. {q.text}</legend>{q.options.map((v:string,j:number)=><label className={'quiz-option '+(answers[i]===j?'chosen':'')} key={j}><input type="radio" name={'q'+i} required checked={answers[i]===j} onChange={()=>setAnswers({...answers,[i]:j})}/><span>{v}</span></label>)}</fieldset>)}<Button disabled={busy}>Шалгалт илгээх <ArrowRight size={15}/></Button></form>}</section>:<div className="notice"><LockKeyhole/><p>Видео бүрэн үзсэнийг сервер баталгаажуулсны дараа шалгалт нээгдэнэ.</p></div>}</>}
 function TasksSelf(){const allMine=tasks.filter((t:any)=>t.user_id===user.id&&t.active);return <><HeaderAction title="Миний өдөр тутмын To-Do" sub={`${date} · Улаанбаатарын цаг`}/><div className="panel"><div className="panel-title"><h2>Өнөөдрийн даалгавар</h2><Badge>{myDone.length}/{myTasks.length}</Badge></div><Progress value={myTasks.length?myDone.length/myTasks.length*100:0}/>{TaskRows({})}</div><div className="panel"><h2>Бүх идэвхтэй оноолт</h2>{allMine.map((t:any)=><div className="task-row" key={t.id}><CalendarDays size={18}/><div className="task-detail"><strong>{t.title}</strong><small>{t.date} · {freq[t.recurrence]}</small></div><span>{t.time}</span></div>)}{!allMine.length&&<Empty title="Оноолт хараахан алга"/>}</div><div className="panel"><h2>Гүйцэтгэлийн түүх</h2>{completions.filter((c:any)=>c.user_id===user.id).slice(0,30).map((c:any)=><div className="version-row" key={c.id}><div><CheckCircle2 size={16}/><span>{tasks.find((t:any)=>t.id===c.task_id)?.title}</span></div><small>{c.date}</small></div>)}</div></>}
 function Dashboard(){const admin=user.role==='admin';const manager=user.role==='manager';const parent=user.role==='parent';const navItems:any[]=admin?[[LayoutDashboard,'Хяналтын самбар','/admin'],[ImageIcon,'Вэбсайт CMS','/admin/cms'],[Users,'Хэрэглэгчид','/admin/users'],[Building2,'Байгууллагууд','/admin/organizations'],[Mail,'Хүсэлтүүд','/admin/applications'],[ClipboardList,'To-Do менежер','/admin/tasks'],[BookOpen,'Academy LMS','/admin/academy'],[TrendingUp,'Аналитик тайлан','/admin/reports'],[Bell,'Мэдэгдэл, имэйл','/admin/notifications'],[Settings,'Тохиргоо','/admin/settings']]:[[LayoutDashboard,parent?'Хяналтын самбар':manager?'Байгууллагын удирдлага':'Нүүр',homeFor(user)],...(manager?[[ClipboardList,'Даалгавар оноолт','/company/tasks'],[TrendingUp,'Тайлан, аудит','/company/reports']]:[]),[BookOpen,'JURA Academy','/academy'],[ClipboardList,'Миний даалгавар','/tasks'],[TrendingUp,'Миний ахиц','/progress'],[Settings,'Тохиргоо','/settings']];let content:any;
 const adminPath=path.startsWith('/admin');if(adminPath&&!admin)content=<Empty title="Хандах эрхгүй" text="Энэ хэсгийг зөвхөн админ ашиглана."/>;else if(path==='/admin')content=AdminHome();else if(path==='/admin/users')content=AdminUsers();else if(path==='/admin/organizations')content=Organizations();else if(path==='/admin/applications')content=Applications();else if(['/admin/tasks','/company/tasks'].includes(path))content=admin||manager?TasksAdmin():<Empty title="Хандах эрхгүй"/>;else if(path==='/admin/academy')content=AcademyAdmin();else if(path==='/admin/cms')content=CMS();else if(['/admin/reports','/company/reports'].includes(path))content=admin||manager?Reports():<Empty title="Хандах эрхгүй"/>;else if(path==='/admin/notifications')content=Notifications();else if(['/settings','/admin/settings'].includes(path))content=SettingsPage();else if(path==='/company')content=manager||admin?Company():<Empty title="Хандах эрхгүй"/>;else if(path==='/parent')content=parent||admin?Parent():<Empty title="Хандах эрхгүй"/>;else if(path==='/tasks')content=TasksSelf();else if(path.startsWith('/academy/'))content=LessonView();else if(path==='/academy')content=<><Banner type="academy" title="Амьдралд хэрэгжих мэдлэг. Өдөр бүрийн өөрчлөлт." sub="Өөртөө хөрөнгө оруулж, жижиг алхмаар урагшилъя."/><div className="toolbar panel"><div className="category-tabs">{['all','personal','work','kids'].map(c=><button className={filter===c?'active':''} key={c} onClick={()=>setFilter(c)}>{c==='all'?'Бүх сургалт':'JURA '+c.toUpperCase()}</button>)}</div>{SearchBox()}</div>{LessonCards()}</>;else if(path==='/progress')content=<><HeaderAction title="Миний ахиц"/><section className="panel"><h2>7 хоногийн гүйцэтгэл</h2><Trend completions={completions.filter((c:any)=>c.user_id===user.id)}/></section><section className="panel"><h2>Шалгалтын үр дүн</h2>{data.attempts.filter((a:any)=>a.user_id===user.id).map((a:any)=><div className="version-row" key={a.id}><div>{lessons.find((l:any)=>l.id===a.lesson_id)?.title||'Хичээл'}<small>{fmt(a.created_at)}</small></div><Badge tone={a.passed?'green':''}>{a.score}/5</Badge></div>)}{!data.attempts.some((a:any)=>a.user_id===user.id)&&<Empty title="Шалгалтын үр дүн алга"/>}</section></>;else content=PersonalDash();
 return <div className="app-shell"><aside className={'sidebar '+(mobile?'open':'')}><a className="side-brand" href="/" onClick={e=>{e.preventDefault();go('/')}}><Logo/></a><nav>{navItems.map(([Icon,t,p])=><a className={path===p?'active':''} key={p} href={p} onClick={e=>{e.preventDefault();go(p)}}><Icon size={18}/><span>{t}</span>{p==='/admin/applications'&&data.applications.some((a:any)=>a.status==='Шинэ')&&<i className="nav-dot"/>}</a>)}</nav><div className="sidebar-bottom"><div className="side-promo" style={{backgroundImage:`linear-gradient(0deg,#12130fe0,transparent),url('${img}premium-office.webp')`}}><span className="eyebrow">SMALL CHANGES</span><h3>Жижиг өөрчлөлт.<br/>Том боломж.</h3><p>Өдөр бүр нэг алхам.</p></div><button onClick={()=>go('/')}><Home size={17}/> Үндсэн сайт</button><button onClick={async()=>{try{await api('logout');setUser(null);setData(null);go('/login')}catch(e:any){setError(e.message)}}}><LogOut size={17}/> Гарах</button></div></aside>{mobile&&<button className="sidebar-overlay" onClick={()=>setMobile(false)} aria-label="Цэс хаах"/>}<div className="app-body"><header className="app-topbar"><div className="top-left"><button className="mobile-menu" onClick={()=>setMobile(!mobile)} aria-label="Цэс"><Menu/></button><span className="breadcrumb">JURA <ChevronRight size={12}/> {navItems.find(x=>x[2]===path)?.[1]||'Миний кабинет'}</span></div><div className="top-right"><span className="top-date">{date} · Улаанбаатар</span><button className="icon-btn" aria-label="Мэдэгдэл" onClick={()=>go(admin?'/admin/notifications':'/tasks')}><Bell size={18}/>{admin&&data.applications.some((a:any)=>a.status==='Шинэ')&&<i className="notification-dot"/>}</button><div className="profile"><span className="avatar">{user.name.charAt(0)}</span><div><strong>{user.name}</strong><small>{roleNames[user.role]}</small></div></div></div></header><main className="dashboard-content">{content}</main><div className="app-footer"><span>JURA Consulting © 2026</span><span>Жижиг өөрчлөлт. Том боломж.</span></div></div></div>}
 function Modal(){if(!modal)return null;const m=modal;const f=m.form;const title:any={user:f?.id?'Хэрэглэгч засах':'Шинэ хэрэглэгч',organization:'Байгууллагын бүртгэл',task:f?.id?'Даалгавар засах':'Даалгавар оноох',lesson:f?.id?'Хичээл засах':'Шинэ хичээл',application:'Хүсэлтийн дэлгэрэнгүй',complete:'Гүйцэтгэл баталгаажуулах',privacy:'Нууцлалын мэдээлэл',submitted:'Хүсэлт хүлээн авлаа'};const save=async(e:any)=>{if(m.type==='user')await perform('saveUser',f);if(m.type==='organization')await perform('organization',f);if(m.type==='task')await perform('task',f);if(m.type==='lesson')await perform('lesson',f);if(m.type==='complete')await perform('complete',{...f,done:true},'Гүйцэтгэлийг хадгаллаа.');setModal(null)};return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)setModal(null)}}><section className={'modal '+(['lesson','application'].includes(m.type)?'wide':'')} role="dialog" aria-modal="true" aria-label={title[m.type]}><header><div><span className="eyebrow">JURA CONSULTING</span><h2>{title[m.type]}</h2></div><button aria-label="Хаах" className="icon-btn" onClick={()=>setModal(null)} disabled={busy}><X/></button></header>{error&&<div className="inline-error" role="alert">{error}</div>}{['user','organization','task','lesson','complete'].includes(m.type)?<form onSubmit={onSubmit(save)}>
 {m.type==='organization'&&<Field label="Байгууллагын нэр *" value={f.name} onChange={(e:any)=>updateModal('name',e.target.value)} required/>}
 {m.type==='user'&&<><div className="fields"><Field label="Овог, нэр *" value={f.name} onChange={(e:any)=>updateModal('name',e.target.value)} required/><Field label="Нэвтрэх нэр *" value={f.username} pattern="[-a-zA-Z0-9_.@]{3,80}" onChange={(e:any)=>updateModal('username',e.target.value)} required/><Field label="Имэйл" type="email" value={f.email} onChange={(e:any)=>updateModal('email',e.target.value)}/><Field label="Утас" value={f.phone} onChange={(e:any)=>updateModal('phone',e.target.value)}/><Field label="Хэрэглэгчийн эрх *"><select value={f.role} onChange={e=>updateModal('role',e.target.value)}>{Object.keys(roleNames).map(r=><option key={r} value={r}>{roleNames[r]}</option>)}</select></Field><Field label="Төлөв"><select value={f.status} onChange={e=>updateModal('status',e.target.value)}><option value="active">Идэвхтэй</option><option value="suspended">Түдгэлзсэн</option></select></Field></div>{['manager','work'].includes(f.role)&&<Field label="Байгууллага *"><select value={f.organization_id||''} onChange={e=>updateModal('organization_id',e.target.value)} required><option value="">Сонгох</option>{data.organizations.map((o:any)=><option key={o.id} value={o.id}>{o.name}</option>)}</select></Field>}{f.role==='kids'&&<><Field label="Үндсэн эцэг эх *"><select value={f.parent_id||''} onChange={e=>updateModal('parent_id',e.target.value)} required><option value="">Эцэг эх сонгох</option>{list.filter((u:any)=>u.role==='parent'&&u.status==='active').map((u:any)=><option key={u.id} value={u.id}>{u.name}</option>)}</select></Field><label className="check-label"><input type="checkbox" checked={f.consent} onChange={e=>updateModal('consent',e.target.checked)} required/><span>Асран хамгаалагчийн зөвшөөрөл, холбоо барих мэдээллийг админ баталгаажуулсан. Зөвшөөрлийн огноо аудитад хадгалагдана.</span></label></>}<Field label={f.id?'Нууц үг шинэчлэх · хоосон бол хэвээр':'Анхны нууц үг * · 10+ тэмдэгт'} type="password" value={f.password} autoComplete="new-password" minLength={10} onChange={(e:any)=>updateModal('password',e.target.value)} required={!f.id}/><p className="muted">Нэвтрэх мэдээллийг хэрэглэгчид өөрийн баталгаатай сувгаар дамжуулна.</p></>}
 {m.type==='task'&&<><Field label="Хэрэглэгч *"><select value={f.user_id} onChange={e=>updateModal('user_id',e.target.value)} required><option value="">Сонгох</option>{list.filter((u:any)=>user.role==='admin'||u.role==='work').map((u:any)=><option key={u.id} value={u.id}>{u.name} · {roleNames[u.role]}</option>)}</select></Field><Field label="Даалгаврын нэр *" value={f.title} onChange={(e:any)=>updateModal('title',e.target.value)} required/><Field label="Дэлгэрэнгүй заавар"><textarea value={f.description} onChange={e=>updateModal('description',e.target.value)}/></Field><div className="fields"><Field label="Эхлэх огноо *" type="date" value={f.date} onChange={(e:any)=>updateModal('date',e.target.value)} required/><Field label="Хийх цаг · Улаанбаатар *" type="time" value={f.time} onChange={(e:any)=>updateModal('time',e.target.value)} required/><Field label="Давтамж"><select value={f.recurrence} onChange={e=>updateModal('recurrence',e.target.value)}>{Object.keys(freq).map(k=><option key={k} value={k}>{freq[k]}</option>)}</select></Field><Field label="Ач холбогдол"><select value={f.priority} onChange={e=>updateModal('priority',e.target.value)}><option value="normal">Энгийн</option><option value="high">Өндөр</option></select></Field></div><label className="check-label"><input type="checkbox" checked={f.evidence_required} onChange={e=>updateModal('evidence_required',e.target.checked)}/>Зурагтай баталгаа шаардана</label><label className="check-label"><input type="checkbox" checked={f.active} onChange={e=>updateModal('active',e.target.checked)}/>Идэвхтэй</label></>}
 {m.type==='lesson'&&<><div className="fields"><Field label="Хичээлийн нэр *" value={f.title} onChange={(e:any)=>updateModal('title',e.target.value)} required/><Field label="Модуль" value={f.module} onChange={(e:any)=>updateModal('module',e.target.value)}/><Field label="Ангилал"><select value={f.category} onChange={e=>updateModal('category',e.target.value)}>{['all','personal','work','kids'].map(k=><option key={k}>{k}</option>)}</select></Field><Field label="Дараалал" type="number" value={f.position} onChange={(e:any)=>updateModal('position',Number(e.target.value))}/></div><Field label="Хичээлийн тайлбар"><textarea value={f.description} onChange={e=>updateModal('description',e.target.value)}/></Field><div className="fields"><Field label="Нүүр зургийн зам" value={f.thumbnail} onChange={(e:any)=>updateModal('thumbnail',e.target.value)}/><Field label="Видео хугацаа · секунд" type="number" min="0" max="14400" value={f.duration} onChange={(e:any)=>updateModal('duration',Number(e.target.value))}/></div><label className="upload-zone"><Upload/><span>{f.video?'Видео байршуулсан · солих':'MP4 / WebM видео байршуулна · 32 MB хүртэл'}</span><input type="file" accept="video/mp4,video/webm" onChange={async e=>{if(e.target.files?.[0])try{const file=e.target.files[0];const v=document.createElement('video');const object=URL.createObjectURL(file);v.preload='metadata';v.src=object;v.onloadedmetadata=()=>{updateModal('duration',Math.ceil(v.duration));URL.revokeObjectURL(object)};const url=await upload(file,'video');updateModal('video',url)}catch{}}}/></label>{f.video&&<div className="notice success"><CheckCircle2 size={16}/><small>Видео хадгалагдсан: {f.video}</small></div>}<h3 className="quiz-editor-heading">Шалгалтын яг 5 асуулт</h3>{f.questions.map((q:any,i:number)=><div className="question-editor" key={i}><Field label={`${i+1}. Асуулт`} value={q.text} onChange={(e:any)=>{const qs=[...f.questions];qs[i]={...q,text:e.target.value};updateModal('questions',qs)}} required={f.status==='published'}/><div className="fields">{q.options.map((o:string,j:number)=><Field key={j} label={`Сонголт ${String.fromCharCode(65+j)}`} value={o} onChange={(e:any)=>{const qs=[...f.questions];qs[i]={...q,options:q.options.map((v:string,k:number)=>j===k?e.target.value:v)};updateModal('questions',qs)}} required={f.status==='published'}/>)}</div><Field label="Зөв хариулт"><select value={q.correct} onChange={e=>{const qs=[...f.questions];qs[i]={...q,correct:Number(e.target.value)};updateModal('questions',qs)}}>{['A','B','C','D'].map((v,j)=><option value={j} key={v}>{v}</option>)}</select></Field></div>)}<Field label="Хичээлийн төлөв"><select value={f.status} onChange={e=>updateModal('status',e.target.value)}><option value="draft">Ноорог</option><option value="published">Нийтлэх</option><option value="archived">Архивлах</option></select></Field></>}
 {m.type==='complete'&&<><h3>{m.title}</h3><label className="upload-zone"><ImageIcon/><span>{f.evidence?'Зураг хадгалагдсан · солих':'Гүйцэтгэлийн зургаа оруулах · 6 MB хүртэл'}</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={async e=>{if(e.target.files?.[0])try{updateModal('evidence',await upload(e.target.files[0],'evidence'))}catch{}}}/></label>{f.evidence&&<img className="evidence-preview" src={f.evidence} alt="Гүйцэтгэлийн зураг"/>}<Field label="Гүйцэтгэлийн тайлбар"><textarea value={f.note} onChange={e=>updateModal('note',e.target.value)}/></Field></>}
 <div className="form-actions"><Button type="button" className="secondary" onClick={()=>setModal(null)}>Болих</Button><Button disabled={busy}>{busy?'Хадгалж байна…':'Хадгалах'} <Check size={16}/></Button></div></form>:m.type==='application'?<><div className="application-detail"><Badge>{f.type.toUpperCase()}</Badge><h3>{f.name}</h3><a href={'tel:'+f.phone}>{f.phone}</a><a href={'mailto:'+f.email}>{f.email}</a><small>{fmt(f.created_at)} · {f.id}</small></div><dl className="detail-list">{Object.entries(f.parsed).map(([k,v]:any)=><div key={k}><dt>{({goal:'Зорилго',problem:'Асуудал',comment:'Тайлбар',company:'Байгууллага',employees:'Ажилтны тоо',position:'Албан тушаал',childName:'Хүүхдийн нэр',age:'Нас',school:'Сургууль',grade:'Анги',hobby:'Сонирхол',relationship:'Хамаарал',consent:'Зөвшөөрөл',consentAt:'Зөвшөөрсөн огноо',consentVersion:'Зөвшөөрлийн хувилбар'} as any)[k]||k}</dt><dd>{typeof v==='boolean'?v?'Тийм':'Үгүй':v||'—'}</dd></div>)}</dl><div className="fields"><Field label="Төлөв"><select value={f.status} onChange={e=>updateModal('status',e.target.value)}>{statuses.map(s=><option key={s}>{s}</option>)}</select></Field><Field label="Хариуцагч"><select value={f.assignee||''} onChange={e=>updateModal('assignee',e.target.value)}><option value="">Оноогоогүй</option>{list.filter((u:any)=>['admin','manager'].includes(u.role)).map((u:any)=><option key={u.id} value={u.id}>{u.name}</option>)}</select></Field></div><Button disabled={busy} onClick={()=>perform('applicationStatus',{id:f.id,status:f.status,assignee:f.assignee}).catch(()=>{})}>Төлөв хадгалах</Button><hr/><h3>Дотоод тэмдэглэл</h3>{data.notes.filter((n:any)=>n.application_id===f.id).map((n:any)=><div className="app-note" key={n.id}><p>{n.body}</p><small>{n.author} · {fmt(n.created_at)}</small></div>)}<form onSubmit={onSubmit(async()=>{await perform('note',{id:f.id,body:m.note});setModal((x:any)=>({...x,note:''}))})}><textarea required placeholder="Тэмдэглэл бичих…" value={m.note} onChange={e=>setModal({...m,note:e.target.value})}/><Button disabled={busy}>Тэмдэглэл нэмэх</Button></form></>:m.type==='privacy'?<div className="privacy-copy"><p>Таны оруулсан мэдээллийг JURA Consulting үйлчилгээний хүсэлт шийдвэрлэх, хэрэглэгчийн эрх нээх, даалгавар болон сургалтын ахицыг бүртгэхэд ашиглана.</p><p>Байгууллагын мэдээлэл тухайн байгууллагын эрх бүхий удирдлагад, хүүхдийн ахиц зөвхөн холбоотой эцэг эх болон админд харагдана. Хүүхдийн хувийн мэдээллийг мэдэгдлийн имэйлд оруулахгүй.</p><p>Хүүхдийн эрхийг асран хамгаалагчийн зөвшөөрлийг админ баталгаажуулсны дараа нээнэ. Мэдээллээ авах, засуулах, устгуулах хүсэлтээ <a href={'mailto:'+contact.email}>{contact.email}</a> хаягаар гаргана уу.</p><p>Нэвтрэх сесс 24 цаг хүчинтэй. Нууц үгийг буцааж тайлах боломжгүй хэш хэлбэрээр хадгална.</p></div>:m.type==='submitted'?<div className="submitted"><CheckCircle2 size={50}/><h3>Баярлалаа!</h3><p>Таны хүсэлт системд хадгалагдлаа.<br/>Бид тантай холбогдоно.</p><small>Хүсэлтийн дугаар: {m.id}</small><Button onClick={()=>setModal(null)}>Ойлголоо</Button></div>:null}</section></div>}
 return <>{loading?<div className="full-loading"><Logo light/><span className="spinner"/><p>JURA платформыг уншиж байна…</p></div>:publicPage?Public():isLogin?Login():!user?<>{PublicNav()}<main className="auth-required"><LockKeyhole size={40}/><h1>Өөрийн кабинетад нэвтэрнэ үү.</h1><p>Админаас олгосон эрхээ ашиглана.</p><Button onClick={()=>go('/login')}>Нэвтрэх <ArrowRight size={16}/></Button></main>{Footer()}</>:!data?<div className="loading-state">Өгөгдөл уншиж байна… <Button onClick={()=>refresh().catch(e=>setError(e.message))}>Дахин оролдох</Button></div>:Dashboard()}{error&&!isLogin&&!modal&&<div className="error-toast" role="alert"><AlertCircle size={19}/><span>{error}</span><button onClick={()=>setError('')} aria-label="Хаах"><X size={17}/></button></div>}{toast&&<div className="toast" role="status"><CheckCircle2 size={19}/>{toast}</div>}{modal&&Modal()}</>
}
